        i0.ɵɵelementStart(166, "h3", 73);
        i0.ɵɵtext(167, "Privacy Policy");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(168, "p", 74);
        i0.ɵɵtext(169, "Overview");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(170, "p");
        i0.ɵɵtext(171, "GoPermit is a parking management company for privately owned sites. GoPermit is the \u2018data controller\u2019 for the purpose of General Data Protection Regulation. This policy has been produced and will continue to be updated in line with the Data Protection Act 2018 and General Data Protection Regulation. This policy will explain your rights and what to expect when we \u2018the data controller\u2019 collect personal data from you, including information about the right to access the information obtained. GoPermit has authorization from \u2018Landowners\u2019 to manage and operate their car parks using a variety of different services. This may include Enforcement officers patrolling our sites, ANPR, MNPR, and CCTV monitoring.");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(172, "p", 74);
        i0.ɵɵtext(173, "What we do");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(174, "p");
        i0.ɵɵtext(175, "We monitor the entry and exit of our privately managed ANPR, CCTV, or patrolled car park sites. We obtain images of people and vehicles, including vehicle registration numbers. These are obtained to confirm the length of stay and enforce non-compliance of the Terms and Conditions of entry onto our privately-owned sites. We also use our cameras to detect and deter criminal activity and to provide activity information to our clients.");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(176, "p", 74);
        i0.ɵɵtext(177, "Who we are");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(178, "p");
        i0.ɵɵtext(179, "GoPermit is a company registered in England and Wales whose registered office is at Office 2, 51 Pinfold Street, Birmingham, West Midlands, B2 4AY.");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(180, "p");
        i0.ɵɵtext(181, "Our Data Protection Team can be contacted by emailing ");
        i0.ɵɵelementStart(182, "a", 67);
        i0.ɵɵtext(183, "support@gopermit.co.uk");
        i0.ɵɵelementEnd();
        i0.ɵɵtext(184, ".");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(185, "p", 74);
        i0.ɵɵtext(186, "What data do we collect?");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(187, "p");
        i0.ɵɵtext(188, "We collect data for the purposes of delivering our services, which include, but are not limited to, executing parking charge notices to motorists deemed to be in contravention of our contractual terms and conditions upheld on behalf of our client.");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(189, "p");
        i0.ɵɵtext(190, "The data we collect comprises images of vehicles within the premises or the VRM (Vehicle Registration Mark) and may include written notes as supporting evidence of a motorist failing to comply with site terms and also vehicle movements during the period of contravention.");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(191, "p", 74);
        i0.ɵɵtext(192, "How do we collect data?");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(193, "ul")(194, "li");
        i0.ɵɵtext(195, "If you are the registered keeper of a vehicle which has had a Parking Charge Notice issued against it, your details will be requested by the DVLA (Driving Vehicle Licensing Agency).");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(196, "li");
        i0.ɵɵtext(197, "If you are not the registered keeper of the vehicle, there are other methods we use to obtain your information, including if you no longer live at the address held by the DVLA.");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(198, "li");
        i0.ɵɵtext(199, "A third party has confirmed that the vehicle was on hire or lease to you at the time of contravention.");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(200, "li");
        i0.ɵɵtext(201, "A third party has confirmed you were either accountable or driving the vehicle at the time of contravention.");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(202, "li");
        i0.ɵɵtext(203, "A third party credit reference.");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(204, "li");
        i0.ɵɵtext(205, "A third party living at the residence who can confirm you no longer live at the address.");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(206, "li");
        i0.ɵɵtext(207, "A third party passing over forwarding addresses.");
        i0.ɵɵelementEnd()();
        i0.ɵɵelement(208, "hr", 75);
        i0.ɵɵelementStart(209, "p");
        i0.ɵɵtext(210, "Euro Parking Services, for the purposes set out in this Privacy Policy, may share information related to a Parking Charge with the following services:");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(211, "ul")(212, "li");
        i0.ɵɵtext(213, "The payment processor for the processing of any online payments.");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(214, "li");
        i0.ɵɵtext(215, "The International Parking Community for auditing purposes of our car park management services.");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(216, "li");
        i0.ɵɵtext(217, "The DVLA (Driver Vehicle Licensing Agency) for the purpose of obtaining registered keeper details.");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(218, "li");
        i0.ɵɵtext(219, "The Independent Appeal Service (IAS) for the purpose of considering any appeal made.");
