        i0.ɵɵelementStart(226, "li");
        i0.ɵɵtext(227, "Collection Agents for the purpose of enforcing a parking contract.");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(228, "li");
        i0.ɵɵtext(229, "Gladstone\u2019s Solicitors or any third party they may instruct on their behalf for the purpose of enforcing a parking contract or responding to a legal query or any other duty authorized sub-contractor.");
        i0.ɵɵelementEnd()();
        i0.ɵɵelementStart(230, "p");
        i0.ɵɵtext(231, "Other than stated above, information supplied to us is subject to confidentiality and will not be disclosed otherwise without your prior consent.");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(232, "p");
        i0.ɵɵtext(233, "We will not ask you for any more information than we need, and we do not keep your information for any longer than necessary.");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(234, "p");
        i0.ɵɵtext(235, "We take reasonable steps to keep your details up to date and accurate. Please keep in mind that we may hold your records after your appeal has been considered, as we are required to have effective audit trails and to comply with regulatory and legislative requirements.");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(236, "p", 74);
        i0.ɵɵtext(237, "Your Rights and Data Security");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(238, "p");
        i0.ɵɵtext(239, "The General Data Protection Regulation gives you the right to access information held about you. You can access personal data we hold about you by sending an email to ");
        i0.ɵɵelementStart(240, "a", 67);
        i0.ɵɵtext(241, "support@gopermit.co.uk");
        i0.ɵɵelementEnd();
        i0.ɵɵtext(242, ".");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(243, "p");
        i0.ɵɵtext(244, "As an organisation, we look after your personal data by implementing security measures appropriate to its nature and the potential harm that might result from a breach. However, please note that the transmission of information via the internet is not completely secure. While we strive to protect your personal data, we cannot guarantee its security during transmission to our site. Any transmission is at your own risk. Once we have received your information, we will use strict procedures and security features to prevent unauthorised access.");
        i0.ɵɵelementEnd();
        i0.ɵɵelement(245, "hr", 75);
        i0.ɵɵelementStart(246, "p", 74);
        i0.ɵɵtext(247, "The Legal Position");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(248, "p");
        i0.ɵɵtext(249, "This privacy notice includes the following information to help you understand clearly how your data is being used:");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(250, "ul")(251, "li");
        i0.ɵɵtext(252, "The lawful basis for processing your data");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(253, "li");
        i0.ɵɵtext(254, "Categories of data processed");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(255, "li");
        i0.ɵɵtext(256, "What we do with your personal data");
        i0.ɵɵelementEnd()();
        i0.ɵɵelementStart(257, "p", 74);
        i0.ɵɵtext(258, "Your Rights Under the Data Protection Act (DPA)");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(259, "ul")(260, "li");
        i0.ɵɵtext(261, "The right to be informed");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(262, "li");
        i0.ɵɵtext(263, "The right of access");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(264, "li");
        i0.ɵɵtext(265, "The right to rectification");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(266, "li");
        i0.ɵɵtext(267, "The right to erasure");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(268, "li");
        i0.ɵɵtext(269, "The right to restrict processing");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(270, "li");
        i0.ɵɵtext(271, "The right to data portability");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(272, "li");
        i0.ɵɵtext(273, "The right to object");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(274, "li");
        i0.ɵɵtext(275, "Rights in relation to automated decision-making and profiling");
        i0.ɵɵelementEnd()();
        i0.ɵɵelementStart(276, "p");
        i0.ɵɵtext(277, "Please note that you have the right to request the above. However, when we receive your request, we may object if we do not agree with it. If you do make a request, we will inform you whether it has been granted or not and provide the reason why.");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(278, "p", 74);
        i0.ɵɵtext(279, "Right of Access");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(280, "p");
        i0.ɵɵtext(281, "You have the right to submit a Subject Access Request, which can be done via an email request to our Data Protection Officer (DPO). We will need to obtain proof of your identity before providing you with information we hold about you. You can make a request by emailing ");
        i0.ɵɵelementStart(282, "a", 67);
        i0.ɵɵtext(283, "support@gopermit.co.uk");
        i0.ɵɵelementEnd();
        i0.ɵɵtext(284, " or calling ");
        i0.ɵɵelementStart(285, "a", 76);
        i0.ɵɵtext(286, "0845 121 0065");
        i0.ɵɵelementEnd();
        i0.ɵɵtext(287, ". For more information about data protection, please visit the ");
        i0.ɵɵelementStart(288, "a", 77);
        i0.ɵɵtext(289, "ICO website");
        i0.ɵɵelementEnd();
        i0.ɵɵtext(290, ".");
        i0.ɵɵelementEnd();
        i0.ɵɵelement(291, "hr", 75);
        i0.ɵɵelementStart(292, "p", 74);
        i0.ɵɵtext(293, "Our Legitimate Interest for Processing Your Personal Data");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(294, "p");
        i0.ɵɵtext(295, "The processing is necessary for a contract which has been entered into and there is a legitimate interest to do so. We are entitled to:");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(296, "ul")(297, "li");
        i0.ɵɵtext(298, "Pursue a motorist for an unpaid parking tariff");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(299, "li");
        i0.ɵɵtext(300, "Pursue a motorist for an unpaid parking charge");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(301, "li");
        i0.ɵɵtext(302, "Ensure safety and security and help deter/detect criminal activity");
        i0.ɵɵelementEnd()();
        i0.ɵɵelementStart(303, "p", 74);
        i0.ɵɵtext(304, "Sharing Your Personal Data");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(305, "p");
        i0.ɵɵtext(306, "Your personal data may be shared for the payment of a parking tariff or charge with third parties, such as a payment facilitator, an external software provider, debt recovery companies, solicitors, and high court officers/bailiffs where necessary to ensure compliance with your obligations under the contract. We will not transfer your personal data outside of the EU.");
        i0.ɵɵelementEnd();
        i0.ɵɵelement(307, "hr", 75);
        i0.ɵɵelementStart(308, "p", 74);
        i0.ɵɵtext(309, "The Five Categories of \u201CPersonal Data\u201D We Process");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(310, "p")(311, "strong");
        i0.ɵɵtext(312, "Unpaid Charge/Tariff:");
        i0.ɵɵelementEnd()();
        i0.ɵɵelementStart(313, "p");
        i0.ɵɵtext(314, "As a compliant user of our privately managed car parking site, the personal data we obtain is your registration number. We may capture images of the vehicle, occupants, or bystanders. Your data will be retained for 3 months only, after which it will be erased.");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(315, "p")(316, "strong");
        i0.ɵɵtext(317, "Unpaid Fee:");
        i0.ɵɵelementEnd()();
        i0.ɵɵelementStart(318, "p");
        i0.ɵɵtext(319, "Where a fee is payable, we may request personal details of the registered keeper of the vehicle from the Driver and Vehicle Licensing Agency (DVLA) and other third parties, such as registered keepers or hire companies, to assist in resolving any dispute.");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(320, "p")(321, "strong");
        i0.ɵɵtext(322, "Appeals:");
        i0.ɵɵelementEnd()();
        i0.ɵɵelementStart(323, "p");
        i0.ɵɵtext(324, "If you challenge a parking charge and we reject your appeal, we will provide your registration number and parking charge number along with the time and date of the parking event to the Independent Appeals Service (IAS) and/or the International Parking Committee (IPC) for independent adjudication.");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(325, "p")(326, "strong");
        i0.ɵɵtext(327, "Windscreen Parking Charge:");
        i0.ɵɵelementEnd()();
        i0.ɵɵelementStart(328, "p");
        i0.ɵɵtext(329, "If you receive a Parking Charge Notice on your windscreen, we will have obtained your personal details, including images of your vehicle, occupants, bystanders, and the vehicle registration number. If payment is made within 28 days, your personal details will not be retained for longer than 3 months. If unpaid beyond 28 days, we may request personal details from the DVLA and other third parties.");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(330, "p")(331, "strong");
        i0.ɵɵtext(332, "Postal Parking Charge:");
        i0.ɵɵelementEnd()();
        i0.ɵɵelementStart(333, "p");
        i0.ɵɵtext(334, "If you receive a Parking Charge Notice by post, we will have previously obtained your personal details, including images of your vehicle, occupants, bystanders, and the vehicle registration. We will also have obtained personal details of the registered keeper of the vehicle from the DVLA.");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(335, "p", 74);
        i0.ɵɵtext(336, "Personal Details We Obtain");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(337, "p");
        i0.ɵɵtext(338, "The personal details we will obtain include:");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(339, "ul")(340, "li");
        i0.ɵɵtext(341, "The name and address of the registered keeper");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(342, "li");
        i0.ɵɵtext(343, "The make, model, and colour of the vehicle");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(344, "li");
        i0.ɵɵtext(345, "Confirmation of the registration number");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(346, "li");
        i0.ɵɵtext(347, "Any other information that we gather in pursuance of the unpaid fee, including information that is shared by you with us");
        i0.ɵɵelementEnd()();
        i0.ɵɵelementStart(348, "p");
        i0.ɵɵtext(349, "Your data will be held for a sufficient time to enable the fee to be settled by you or another person and to resolve any dispute. However, your data will not normally be held for longer than 6 years. In some circumstances, your data may be held for longer than 6 years. Examples include:");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(350, "ul")(351, "li");
        i0.ɵɵtext(352, "When there is an ongoing dispute requiring us to retain the data for longer than normal.");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(353, "li");
        i0.ɵɵtext(354, "Where a court order has been made allowing us to pursue outstanding money after the expiration of 6 years.");
        i0.ɵɵelementEnd()();
        i0.ɵɵelementStart(355, "p", 74);
        i0.ɵɵtext(356, "Changes to Our Privacy Notice");
        i0.ɵɵelementEnd();
        i0.ɵɵelementStart(357, "p");
        i0.ɵɵtext(358, "From time to time, we may amend the way in which we process personal data. This may lead to changes in how we collect and/or use your personal information. We may amend the terms of this Privacy Policy at any time.");
        i0.ɵɵelementEnd();
        i0.ɵɵelement(359, "hr", 75);
        i0.ɵɵelementStart(360, "p", 74);
        i0.ɵɵtext(361, "GoPermit Website Privacy Policy");
